        "explanation": "Khi muốn phủ định hoặc đặt câu hỏi về chủ đề Dining at a Traditional Restaurant, hãy sử dụng trợ động từ phù hợp với chủ ngữ. Động từ chính luôn quay về dạng nguyên mẫu.",
